import numpy as np


def svd(a: np.ndarray):
    u, singular_values, vt = np.linalg.svd(a, full_matrices=False)
    return u, singular_values, vt


def reconstruct_from_svd(u: np.ndarray, singular_values: np.ndarray, vt: np.ndarray) -> np.ndarray:
    return u @ np.diag(singular_values) @ vt


def low_rank_approximation(a: np.ndarray, k: int) -> np.ndarray:
    u, singular_values, vt = svd(a)
    return u[:, :k] @ np.diag(singular_values[:k]) @ vt[:k, :]

import numpy as np


def is_symmetric(a: np.ndarray) -> bool:
    return np.allclose(a, a.T)


def quadratic_form(a: np.ndarray, x: np.ndarray) -> float:
    return float(x @ a @ x)


def is_positive_definite(a: np.ndarray) -> bool:
    if not is_symmetric(a):
        return False
    eigenvalues = np.linalg.eigvalsh(a)
    return bool(np.all(eigenvalues > 0))

def forward_difference(f, x: float, eps: float = 1e-5) -> float:
    return (f(x + eps) - f(x)) / eps


def central_difference(f, x: float, eps: float = 1e-5) -> float:
    return (f(x + eps) - f(x - eps)) / (2 * eps)

import numpy as np


def partial_derivative(f, x: np.ndarray, index: int, eps: float = 1e-5) -> float:
    x_plus = x.copy()
    x_plus[index] += eps
    x_minus = x.copy()
    x_minus[index] -= eps
    return (f(x_plus) - f(x_minus)) / (2 * eps)


def gradient(f, x: np.ndarray, eps: float = 1e-5) -> np.ndarray:
    return np.array([partial_derivative(f, x, i, eps) for i in range(len(x))])

def compose(f, g):
    return lambda x: f(g(x))


def chain_rule_derivative(f_prime, g, g_prime, x: float) -> float:
    return f_prime(g(x)) * g_prime(x)

