import numpy as np


def class_proportions(labels: np.ndarray) -> dict:
    unique, counts = np.unique(labels, return_counts=True)
    return {label: count / len(labels) for label, count in zip(unique, counts)}


def stratified_sample_indices(labels: np.ndarray, sample_size: int, seed: int | None = None) -> np.ndarray:
    rng = np.random.default_rng(seed)
    proportions = class_proportions(labels)

    selected = []
    for label, proportion in proportions.items():
        class_indices = np.where(labels == label)[0]
        n_from_class = round(proportion * sample_size)
        n_from_class = min(n_from_class, len(class_indices))
        chosen = rng.choice(class_indices, size=n_from_class, replace=False)
        selected.append(chosen)

    return np.concatenate(selected)

import numpy as np


def bootstrap_resample(x: np.ndarray, rng: np.random.Generator) -> np.ndarray:
    return rng.choice(x, size=len(x), replace=True)


def bootstrap_confidence_interval(
    x: np.ndarray,
    statistic_fn,
    n_bootstrap: int = 1000,
    confidence: float = 0.95,
    seed: int | None = None,
) -> tuple[float, float]:
    rng = np.random.default_rng(seed)
    bootstrap_statistics = np.empty(n_bootstrap)
    for i in range(n_bootstrap):
        resample = bootstrap_resample(x, rng)
        bootstrap_statistics[i] = statistic_fn(resample)

    lower_percentile = (1.0 - confidence) / 2.0 * 100.0
    upper_percentile = (1.0 + confidence) / 2.0 * 100.0
    return (
        float(np.percentile(bootstrap_statistics, lower_percentile)),
        float(np.percentile(bootstrap_statistics, upper_percentile)),
    )

import numpy as np
from scipy import stats


def welch_t_statistic(a: np.ndarray, b: np.ndarray) -> float:
    mean_a, mean_b = np.mean(a), np.mean(b)
    var_a, var_b = np.var(a, ddof=1), np.var(b, ddof=1)
    n_a, n_b = len(a), len(b)
    standard_error = np.sqrt(var_a / n_a + var_b / n_b)
    return float((mean_a - mean_b) / standard_error)


def welch_degrees_of_freedom(a: np.ndarray, b: np.ndarray) -> float:
    var_a, var_b = np.var(a, ddof=1), np.var(b, ddof=1)
    n_a, n_b = len(a), len(b)
    numerator = (var_a / n_a + var_b / n_b) ** 2
    denominator = (var_a / n_a) ** 2 / (n_a - 1) + (var_b / n_b) ** 2 / (n_b - 1)
    return float(numerator / denominator)


def two_sample_t_test(a: np.ndarray, b: np.ndarray) -> tuple[float, float]:
    t_statistic = welch_t_statistic(a, b)
    df = welch_degrees_of_freedom(a, b)
    p_value = 2.0 * (1.0 - stats.t.cdf(abs(t_statistic), df))
    return t_statistic, float(p_value)

def is_statistically_significant(p_value: float, alpha: float = 0.05) -> bool:
    return p_value < alpha


def expected_false_positives(num_tests: int, alpha: float = 0.05) -> float:
    return num_tests * alpha


def bonferroni_corrected_alpha(num_tests: int, alpha: float = 0.05) -> float:
    return alpha / num_tests

