import numpy as np


def softmax(Z: np.ndarray) -> np.ndarray:
    Z_shift = Z - np.max(Z, axis=1, keepdims=True)
    exp_Z = np.exp(Z_shift)
    return exp_Z / np.sum(exp_Z, axis=1, keepdims=True)


def cce_loss(P: np.ndarray, y_indices: np.ndarray) -> float:
    n = P.shape[0]
    p_correct = np.clip(P[np.arange(n), y_indices], 1e-12, 1.0)
    return float(-np.mean(np.log(p_correct)))

import numpy as np


def weighted_bce_loss(p: np.ndarray, y: np.ndarray, class_weights: dict) -> float:
    p = np.clip(p, 1e-12, 1 - 1e-12)
    weights = np.where(y == 1, class_weights[1], class_weights[0])
    losses = weights * (y * np.log(p) + (1 - y) * np.log(1 - p))
    return float(-np.mean(losses))

import numpy as np


def bce_with_logits_loss(z: np.ndarray, y: np.ndarray) -> float:
    max_z_zero = np.maximum(z, 0)
    stable_log_term = np.log1p(np.exp(-np.abs(z)))
    per_sample = max_z_zero - z * y + stable_log_term
    return float(np.mean(per_sample))

import numpy as np


def log_softmax(Z: np.ndarray) -> np.ndarray:
    Z_shift = Z - np.max(Z, axis=1, keepdims=True)
    return Z_shift - np.log(np.sum(np.exp(Z_shift), axis=1, keepdims=True))


def nll_loss(log_probs: np.ndarray, y_indices: np.ndarray) -> float:
    n = log_probs.shape[0]
    return float(-np.mean(log_probs[np.arange(n), y_indices]))

import numpy as np

_EPS = 1e-6


def bin_proportions(values: np.ndarray, bin_edges: np.ndarray) -> np.ndarray:
    counts, _ = np.histogram(values, bins=bin_edges)
    return counts / len(values)


def population_stability_index(
    train_values: np.ndarray, live_values: np.ndarray, num_bins: int = 10
) -> float:
    bin_edges = np.quantile(train_values, np.linspace(0.0, 1.0, num_bins + 1))
    bin_edges[0] = -np.inf
    bin_edges[-1] = np.inf

    train_proportions = np.clip(bin_proportions(train_values, bin_edges), _EPS, 1.0)
    live_proportions = np.clip(bin_proportions(live_values, bin_edges), _EPS, 1.0)

    return float(np.sum((live_proportions - train_proportions) * np.log(live_proportions / train_proportions)))


def detect_distribution_shift(
    train_values: np.ndarray, live_values: np.ndarray, num_bins: int = 10, threshold: float = 0.2
) -> bool:
    return population_stability_index(train_values, live_values, num_bins) > threshold

import numpy as np


def gini_impurity(labels: np.ndarray) -> float:
    if labels.size == 0:
        return 0.0
    _, counts = np.unique(labels, return_counts=True)
    probabilities = counts / labels.size
    return float(1.0 - np.sum(probabilities**2))

