def _majority_class(labels: np.ndarray, default: int = 0) -> int:
    if labels.size == 0:
        return default
    values, counts = np.unique(labels, return_counts=True)
    return int(values[np.argmax(counts)])


def build_tree_pre_pruned(
    input: np.ndarray,
    labels: np.ndarray,
    max_depth: int,
    min_samples_leaf: int = 1,
) -> dict:
    default = _majority_class(labels)

    if max_depth == 0 or labels.size < 2 or gini_impurity(labels) == 0.0:
        return {"leaf": True, "prediction": default, "default": default}

    split = find_best_split(input, labels)
    if split is None:
        return {"leaf": True, "prediction": default, "default": default}

    feature, threshold, _ = split
    left_mask = input[:, feature] <= threshold
    if left_mask.sum() < min_samples_leaf or (~left_mask).sum() < min_samples_leaf:
        return {"leaf": True, "prediction": default, "default": default}

    return {
        "leaf": False,
        "feature": feature,
        "threshold": threshold,
        "default": default,
        "left": build_tree_pre_pruned(
            input[left_mask], labels[left_mask], max_depth - 1, min_samples_leaf
        ),
        "right": build_tree_pre_pruned(
            input[~left_mask], labels[~left_mask], max_depth - 1, min_samples_leaf
        ),
    }


def prune_tree(tree: dict, input_val: np.ndarray, labels_val: np.ndarray) -> dict:
    if tree["leaf"]:
        return tree

    left_mask = input_val[:, tree["feature"]] <= tree["threshold"]
    candidate = {
        **tree,
        "left": prune_tree(tree["left"], input_val[left_mask], labels_val[left_mask]),
        "right": prune_tree(tree["right"], input_val[~left_mask], labels_val[~left_mask]),
    }

    subtree_predictions = predict_tree(candidate, input_val)
    subtree_error = int(np.sum(subtree_predictions != labels_val))

    leaf_prediction = _majority_class(labels_val, default=tree["default"])
    leaf_error = int(np.sum(leaf_prediction != labels_val))

    if leaf_error <= subtree_error:
        return {"leaf": True, "prediction": leaf_prediction, "default": tree["default"]}
    return candidate

import numpy as np


def variance(targets: np.ndarray) -> float:
    if targets.size == 0:
        return 0.0
    return float(np.var(targets))


def variance_reduction(
    parent_targets: np.ndarray,
    left_targets: np.ndarray,
    right_targets: np.ndarray,
) -> float:
    n_samples = parent_targets.size
    weighted_child_variance = (left_targets.size / n_samples) * variance(left_targets) + (
        right_targets.size / n_samples
    ) * variance(right_targets)
    return variance(parent_targets) - weighted_child_variance


def find_best_regression_split(
    input: np.ndarray, targets: np.ndarray
) -> tuple[int, float, float] | None:
    n_features = input.shape[1]
    best_reduction, best_feature, best_threshold = 0.0, None, None
    for feature in range(n_features):
        values = np.unique(input[:, feature])
        if values.size < 2:
            continue
        thresholds = (values[:-1] + values[1:]) / 2
        for threshold in thresholds:
            left_mask = input[:, feature] <= threshold
            reduction = variance_reduction(targets, targets[left_mask], targets[~left_mask])
            if reduction > best_reduction:
                best_reduction, best_feature, best_threshold = reduction, feature, threshold
    if best_feature is None:
        return None
    return best_feature, float(best_threshold), float(best_reduction)


def build_regression_tree(input: np.ndarray, targets: np.ndarray, max_depth: int) -> dict:
    if max_depth == 0 or targets.size < 2 or variance(targets) == 0.0:
        return {"leaf": True, "prediction": float(np.mean(targets))}

    split = find_best_regression_split(input, targets)
    if split is None:
        return {"leaf": True, "prediction": float(np.mean(targets))}

    feature, threshold, _ = split
    left_mask = input[:, feature] <= threshold
    return {
        "leaf": False,
        "feature": feature,
        "threshold": threshold,
        "left": build_regression_tree(input[left_mask], targets[left_mask], max_depth - 1),
        "right": build_regression_tree(input[~left_mask], targets[~left_mask], max_depth - 1),
    }


def predict_regression_tree(tree: dict, input: np.ndarray) -> np.ndarray:
    predictions = np.empty(input.shape[0], dtype=float)
    for i in range(input.shape[0]):
        node = tree
        while not node["leaf"]:
            if input[i, node["feature"]] <= node["threshold"]:
                node = node["left"]
            else:
                node = node["right"]
        predictions[i] = node["prediction"]
    return predictions

import numpy as np


def soft_threshold(x: np.ndarray, threshold: float) -> np.ndarray:
    return np.sign(x) * np.maximum(np.abs(x) - threshold, 0.0)


def lasso_regression_coordinate_descent(
    input: np.ndarray, target: np.ndarray, alpha: float = 1.0, epochs: int = 200
) -> tuple[np.ndarray, np.ndarray]:
    n, d = input.shape
    x_mean = input.mean(axis=0)
    y_mean = target.mean()
    x_centered = input - x_mean
    y_centered = target - y_mean

    weight = np.zeros(d)
    for _ in range(epochs):
        for j in range(d):
            residual = y_centered - x_centered @ weight + x_centered[:, j] * weight[j]
            rho_j = (x_centered[:, j] @ residual) / n
            z_j = (x_centered[:, j] @ x_centered[:, j]) / n
            weight[j] = soft_threshold(rho_j, alpha) / z_j if z_j > 0 else 0.0

    bias = y_mean - x_mean @ weight
    return weight.reshape(1, -1), np.array([bias])

from itertools import combinations_with_replacement

import numpy as np


def polynomial_features_multivariate(X: np.ndarray, degree: int) -> np.ndarray:
    n, num_features = X.shape
    columns = []
    for d in range(degree + 1):
        for combo in combinations_with_replacement(range(num_features), d):
            column = np.ones(n)
            for feature_index in combo:
                column = column * X[:, feature_index]
            columns.append(column)
    return np.stack(columns, axis=1)

