import numpy as np


def hinge_loss(scores: np.ndarray, target: np.ndarray, reduction: str = "mean") -> float | np.ndarray:
    elementwise = np.maximum(0.0, 1.0 - target * scores)
    if reduction == "mean":
        return float(np.mean(elementwise))
    elif reduction == "sum":
        return float(np.sum(elementwise))
    elif reduction == "none":
        return elementwise
    else:
        raise ValueError(f"Invalid reduction: {reduction!r}")

import numpy as np


def functional_margin(weight: np.ndarray, bias: float, X: np.ndarray, y: np.ndarray) -> np.ndarray:
    scores = X @ weight + bias
    return y * scores


def geometric_margin(weight: np.ndarray, bias: float, X: np.ndarray, y: np.ndarray) -> np.ndarray:
    return functional_margin(weight, bias, X, y) / np.linalg.norm(weight)


def dataset_margin(weight: np.ndarray, bias: float, X: np.ndarray, y: np.ndarray) -> float:
    return float(np.min(geometric_margin(weight, bias, X, y)))

import numpy as np


def pairwise_distances(input: np.ndarray, queries: np.ndarray) -> np.ndarray:
    diff = queries[:, np.newaxis, :] - input[np.newaxis, :, :]
    return np.sqrt(np.sum(diff**2, axis=-1))


def knn_predict(input: np.ndarray, labels: np.ndarray, queries: np.ndarray, k: int) -> np.ndarray:
    distances = pairwise_distances(input, queries)
    nearest_indices = np.argsort(distances, axis=1)[:, :k]

    predictions = np.empty(queries.shape[0], dtype=int)
    for i in range(queries.shape[0]):
        neighbor_labels = labels[nearest_indices[i]]
        values, counts = np.unique(neighbor_labels, return_counts=True)
        predictions[i] = values[np.argmax(counts)]
    return predictions

import numpy as np


def bernoulli_nb_fit(input: np.ndarray, labels: np.ndarray, alpha: float = 1.0) -> dict:
    classes = np.unique(labels)
    n_samples = input.shape[0]
    log_priors = {}
    feature_probs = {}
    for c in classes:
        mask = labels == c
        class_count = mask.sum()
        log_priors[c] = float(np.log(class_count / n_samples))
        feature_probs[c] = (input[mask].sum(axis=0) + alpha) / (class_count + 2 * alpha)
    return {"classes": classes, "log_priors": log_priors, "feature_probs": feature_probs}


def bernoulli_log_likelihood(x: np.ndarray, feature_probs: np.ndarray) -> float:
    return float(np.sum(x * np.log(feature_probs) + (1 - x) * np.log(1 - feature_probs)))


def bernoulli_nb_predict(model: dict, queries: np.ndarray) -> np.ndarray:
    classes = model["classes"]
    predictions = np.empty(queries.shape[0], dtype=classes.dtype)
    for i in range(queries.shape[0]):
        scores = [
            model["log_priors"][c]
            + bernoulli_log_likelihood(queries[i], model["feature_probs"][c])
            for c in classes
        ]
        predictions[i] = classes[np.argmax(scores)]
    return predictions

import numpy as np


def gaussian_nb_fit(input: np.ndarray, labels: np.ndarray, var_smoothing: float = 1e-9) -> dict:
    classes = np.unique(labels)
    n_samples = input.shape[0]
    epsilon = var_smoothing * np.var(input, axis=0).max()
    log_priors, means, variances = {}, {}, {}
    for c in classes:
        mask = labels == c
        class_input = input[mask]
        log_priors[c] = float(np.log(mask.sum() / n_samples))
        means[c] = class_input.mean(axis=0)
        variances[c] = class_input.var(axis=0) + epsilon
    return {"classes": classes, "log_priors": log_priors, "means": means, "variances": variances}


def gaussian_log_likelihood(x: np.ndarray, mean: np.ndarray, variance: np.ndarray) -> float:
    return float(np.sum(-0.5 * np.log(2 * np.pi * variance) - ((x - mean) ** 2) / (2 * variance)))


def gaussian_nb_predict(model: dict, queries: np.ndarray) -> np.ndarray:
    classes = model["classes"]
    predictions = np.empty(queries.shape[0], dtype=classes.dtype)
    for i in range(queries.shape[0]):
        scores = [
            model["log_priors"][c]
            + gaussian_log_likelihood(queries[i], model["means"][c], model["variances"][c])
            for c in classes
        ]
        predictions[i] = classes[np.argmax(scores)]
    return predictions

import numpy as np


def kmeans_update_centroids(
    input: np.ndarray, assignments: np.ndarray, centroids: np.ndarray
) -> np.ndarray:
    n_clusters = centroids.shape[0]
    new_centroids = centroids.copy()
    for cluster in range(n_clusters):
        members = input[assignments == cluster]
        if members.shape[0] > 0:
            new_centroids[cluster] = members.mean(axis=0)
    return new_centroids

import numpy as np


def _average_path_length_correction(n: int) -> float:
    if n <= 1:
        return 0.0
    return 2.0 * (np.log(n - 1) + 0.5772156649) - 2.0 * (n - 1) / n


def build_isolation_tree(input: np.ndarray, max_depth: int, rng: np.random.Generator) -> dict:
    n_samples, n_features = input.shape
    if max_depth == 0 or n_samples <= 1:
        return {"leaf": True, "size": n_samples}

    feature = rng.integers(0, n_features)
    column = input[:, feature]
    min_value, max_value = column.min(), column.max()
    if min_value == max_value:
        return {"leaf": True, "size": n_samples}

    threshold = rng.uniform(min_value, max_value)
    left_mask = column < threshold
    if left_mask.sum() == 0 or (~left_mask).sum() == 0:
        return {"leaf": True, "size": n_samples}

    return {
        "leaf": False,
        "feature": feature,
        "threshold": threshold,
        "left": build_isolation_tree(input[left_mask], max_depth - 1, rng),
        "right": build_isolation_tree(input[~left_mask], max_depth - 1, rng),
    }


def path_length(tree: dict, x: np.ndarray, current_depth: int = 0) -> float:
    if tree["leaf"]:
        return current_depth + _average_path_length_correction(tree["size"])
    if x[tree["feature"]] < tree["threshold"]:
        return path_length(tree["left"], x, current_depth + 1)
    return path_length(tree["right"], x, current_depth + 1)


def isolation_forest_fit(
    input: np.ndarray, n_trees: int, max_depth: int, seed: int | None = None
) -> list[dict]:
    rng = np.random.default_rng(seed)
    return [build_isolation_tree(input, max_depth, rng) for _ in range(n_trees)]


def anomaly_scores(forest: list[dict], input: np.ndarray, sample_size: int) -> np.ndarray:
    average_path_lengths = np.array(
        [np.mean([path_length(tree, x) for tree in forest]) for x in input]
    )
    normalization = _average_path_length_correction(sample_size)
    return 2.0 ** (-average_path_lengths / normalization)

