class MetricTracker:
    def __init__(self):
        self.history: dict[str, list[float]] = {}

    def record(self, name: str, value: float) -> None:
        self.history.setdefault(name, []).append(value)

    def get_history(self, name: str) -> list[float]:
        return self.history.get(name, [])

    def moving_average(self, name: str, window: int) -> list[float]:
        values = self.history.get(name, [])
        result = []
        for i in range(len(values)):
            start = max(0, i - window + 1)
            result.append(float(np.mean(values[start : i + 1])))
        return result

    def best(self, name: str, mode: str = "min") -> float | None:
        values = self.history.get(name, [])
        if not values:
            return None
        return min(values) if mode == "min" else max(values)

class EarlyStopping:
    def __init__(self, patience: int = 5, min_delta: float = 0.0):
        self.patience = patience
        self.min_delta = min_delta
        self.best_loss: float | None = None
        self.best_state = None
        self.counter = 0
        self.should_stop = False

    def step(self, val_loss: float, state=None) -> bool:
        if self.best_loss is None or val_loss < self.best_loss - self.min_delta:
            self.best_loss = val_loss
            self.best_state = state
            self.counter = 0
        else:
            self.counter += 1
            if self.counter >= self.patience:
                self.should_stop = True

        return self.should_stop

