def paged_attention_allocate(block_size: int, total_blocks: int, events: list) -> dict:
    free_blocks = list(range(total_blocks))
    seq_tables: dict = {}
    seq_len: dict = {}
    oom_at = None

    for i, (op, seq_id) in enumerate(events):
        if op == "append":
            table = seq_tables.setdefault(seq_id, [])
            n = seq_len.get(seq_id, 0)
            needs_new_block = n % block_size == 0
            if needs_new_block:
                if not free_blocks:
                    oom_at = i
                    break
                table.append(free_blocks.pop(0))
            seq_len[seq_id] = n + 1
        elif op == "free":
            if seq_id in seq_tables:
                free_blocks.extend(seq_tables.pop(seq_id))
                free_blocks.sort()
                seq_len.pop(seq_id, None)
        else:
            raise ValueError(f"unknown op {op!r}")

    return {
        "block_tables": {str(k): v for k, v in seq_tables.items()},
        "free_blocks_remaining": len(free_blocks),
        "out_of_memory_at_event": oom_at,
    }

def _chained_hashes(tokens, block_size):
    hashes = []
    prev = "SEED"
    for start in range(0, len(tokens) - len(tokens) % block_size, block_size):
        block = tuple(tokens[start : start + block_size])
        prev = hash((prev, block))
        hashes.append(prev)
    return hashes


def prefix_cache_lookup(tokens: list, block_size: int, cache_store: list) -> dict:
    cache_store = set(cache_store)
    hashes = _chained_hashes(tokens, block_size)

    blocks_reused = 0
    for h in hashes:
        if h in cache_store:
            blocks_reused += 1
        else:
            break

    reused_tokens = blocks_reused * block_size
    tokens_to_prefill = tokens[reused_tokens:]

    updated_store = cache_store | set(hashes)

    return {
        "blocks_reused": blocks_reused,
        "reused_tokens": reused_tokens,
        "tokens_to_prefill": tokens_to_prefill,
        "updated_cache_store": sorted(str(h) for h in updated_store),
    }

import numpy as np


def quantize_int8_symmetric(x: np.ndarray) -> dict:
    x = np.array(x, dtype=float)
    max_abs = np.max(np.abs(x)) if x.size > 0 else 0.0
    scale = max_abs / 127.0 if max_abs > 0 else 0.0

    if scale == 0.0:
        q = np.zeros_like(x, dtype=int)
    else:
        q = np.clip(np.round(x / scale), -127, 127).astype(int)

    x_hat = q * scale
    return {"quantized": q, "scale": float(scale), "dequantized": x_hat}

import numpy as np


def _percentile(sorted_arr, p):
    n = len(sorted_arr)
    if n == 1:
        return float(sorted_arr[0])
    rank = (p / 100.0) * (n - 1)
    lo = int(np.floor(rank))
    hi = min(lo + 1, n - 1)
    frac = rank - lo
    return float(sorted_arr[lo] + frac * (sorted_arr[hi] - sorted_arr[lo]))


def latency_percentiles(latencies: list, percentiles: tuple = (50, 95, 99)) -> dict:
