def dynamic_request_batching(max_batch_size: int, max_wait_time: float, arrivals: list) -> dict:
    batches = []
    current_batch: list = []
    current_start = None

    for arrival_time, req_id in arrivals:
        if current_batch and arrival_time >= current_start + max_wait_time:
            batches.append({"requests": current_batch, "close_time": current_start + max_wait_time})
            current_batch, current_start = [], None

        if not current_batch:
            current_start = arrival_time
        current_batch.append(req_id)

        if len(current_batch) == max_batch_size:
            batches.append({"requests": current_batch, "close_time": arrival_time})
            current_batch, current_start = [], None

    if current_batch:
        batches.append({"requests": current_batch, "close_time": current_start + max_wait_time})

    return {
        "batches": [b["requests"] for b in batches],
        "close_times": [b["close_time"] for b in batches],
    }

def simulate_continuous_batching(max_batch_size: int, requests: list) -> dict:
    by_arrival = sorted(requests, key=lambda r: r[0])
    queue = list(by_arrival)
    active: dict = {}
    admitted_step: dict = {}
    finished_step: dict = {}
    step = 0

    def admit_arrivals_and_fill():
        nonlocal queue
        still_waiting = []
        for arrival_step, rid, need in queue:
            if arrival_step <= step and len(active) < max_batch_size:
                active[rid] = need
                admitted_step[rid] = step
            else:
                still_waiting.append((arrival_step, rid, need))
        queue = still_waiting

    admit_arrivals_and_fill()

    while active or queue:
        if not active and queue:
            step = queue[0][0]
            admit_arrivals_and_fill()
            continue

        for rid in list(active):
            active[rid] -= 1
            if active[rid] == 0:
                finished_step[rid] = step
                del active[rid]

        step += 1
        admit_arrivals_and_fill()

    return {"admitted_step": admitted_step, "finished_step": finished_step, "total_steps": step}

def chunked_prefill_scheduling(token_budget: int, n_decode_tokens_each: int, requests: list) -> dict:
    by_arrival = sorted(requests, key=lambda r: r[0])
    queue = list(by_arrival)
    prefill_remaining: dict = {}
    decode_remaining: dict = {}
    prefill_done_step: dict = {}
    completed_step: dict = {}
    step = 0
    order: list = []

    def admit_new_arrivals():
        nonlocal queue
        still_waiting = []
        for arrival_step, rid, prefill_tokens in queue:
            if arrival_step <= step:
                prefill_remaining[rid] = prefill_tokens
                order.append(rid)
            else:
                still_waiting.append((arrival_step, rid, prefill_tokens))
        queue = still_waiting

    admit_new_arrivals()

    while prefill_remaining or decode_remaining or queue:
        budget = token_budget
        for rid in list(decode_remaining):
            decode_remaining[rid] -= 1
            budget -= 1
            if decode_remaining[rid] == 0:
                completed_step[rid] = step
                del decode_remaining[rid]

        just_finished_prefill = []
        for rid in list(order):
            if budget <= 0:
                break
            if rid not in prefill_remaining:
                continue
            chunk = min(budget, prefill_remaining[rid])
            prefill_remaining[rid] -= chunk
            budget -= chunk
            if prefill_remaining[rid] == 0:
                prefill_done_step[rid] = step
                just_finished_prefill.append(rid)
                del prefill_remaining[rid]

        for rid in just_finished_prefill:
            order.remove(rid)
            decode_remaining[rid] = n_decode_tokens_each

        step += 1
        admit_new_arrivals()

    return {"prefill_done_step": prefill_done_step, "completed_step": completed_step, "total_steps": step}

